fun checkIfStringIsPalindrome(input: String): Boolean {
    var left = 0
    var right = input.length - 1
    while (left < right) {
        if (input[left] != input[right]) return false
        left++
        right--
    }
    return true

}

fun checkIfStringIsPalindrome(input: String): Boolean {
    val chars = input.toCharArray()
    for (i in chars.indices) {
        if (chars[i] != chars[chars.size - 1 - i]) return false
    }
    return true

}

fun checkIfStringIsPalindrome(input: String): Boolean {
    return input.filter { it.isLetterOrDigit() }.lowercase() == input.filter { it.isLetterOrDigit() }.lowercase().reversed()
}

